template.inlineTemplate:
//KAUDIT   EXEC PGM=IKJEFT01,DYNAMNBR=36,REGION=0M
//SYSTSPRT DD DSN=${instance-STAGE_DATASET},DISP=SHR
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 EX '${instance-REXX_DATASET}(KEYRGAUD)' '${instance-KEYRING_OWNER} ${instance-KEYRING_NAME} ${instance-WARN_DAYS}' EXEC
/*

step.instructions:
Prints a final audit trail entry confirming:
  - System: ${instance-SYSTEM_NAME}
  - Keyring: ${instance-KEYRING_NAME} (owner: ${instance-KEYRING_OWNER})
  - Verdict: ${instance-AUDIT_VERDICT}
  - CSP endpoint: ${instance-CSP_ENDPOINT}
